#include <bits/stdc++.h>
using namespace std;

using i64 = int64_t;
using pii = pair<int,int>;
using vi = vector<int>;

constexpr i64 MOD = 1000000007;

i64 mod_pow(i64 b, i64 e) {
    i64 r = 1;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

int N, half;
i64 dp1[1 << 20], dp2[1 << 20];
i64 prob[10][10];
int rev1[1 << 20], rev2[1 << 20];

void build_first(i64 cur_prob, int step, vi& choice) {
    if (step == half) {
        int mask = 0, idx = 0;
        for (int bs = 0; bs < (1 << N); ++bs) {
            if (__builtin_popcount(bs) != half) continue;
            vi pos;
            for (int i = 0; i < N; ++i) 
                if (bs >> i & 1) pos.push_back(i);
            sort(pos.begin(), pos.end());
            bool found = false;
            do {
                bool ok = true;
                for (int k = 0; k < half; ++k) 
                    if (!(choice[k] >> pos[k] & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(pos.begin(), pos.end()));
            if (found) mask |= 1 << idx;
            ++idx;
        }
        dp1[mask] = (dp1[mask] + cur_prob) % MOD;
        return;
    }

    for (int bs = 0; bs < (1 << N); ++bs) {
        choice.push_back(bs);
        i64 new_prob = cur_prob;
        for (int k = 0; k < N; ++k) {
            if (bs >> k & 1)
                new_prob = new_prob * prob[step][k] % MOD;
            else
                new_prob = new_prob * (MOD + 1 - prob[step][k]) % MOD;
        }
        build_first(new_prob, step + 1, choice);
        choice.pop_back();
    }
}

void build_second(i64 cur_prob, int step, vi& choice) {
    if (step == N) {
        int mask = 0, idx = 0;
        for (int bs = 0; bs < (1 << N); ++bs) {
            if (__builtin_popcount(bs) != N - half) continue;
            vi pos;
            for (int i = 0; i < N; ++i) 
                if (bs >> i & 1) pos.push_back(i);
            sort(pos.begin(), pos.end());
            bool found = false;
            do {
                bool ok = true;
                for (int k = 0; k < N - half; ++k) 
                    if (!(choice[k] >> pos[k] & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(pos.begin(), pos.end()));
            if (found) mask |= 1 << idx;
            ++idx;
        }
        dp2[mask] = (dp2[mask] + cur_prob) % MOD;
        return;
    }

    for (int bs = 0; bs < (1 << N); ++bs) {
        choice.push_back(bs);
        i64 new_prob = cur_prob;
        for (int k = 0; k < N; ++k) {
            if (bs >> k & 1)
                new_prob = new_prob * prob[step][k] % MOD;
            else
                new_prob = new_prob * (MOD + 1 - prob[step][k]) % MOD;
        }
        build_second(new_prob, step + 1, choice);
        choice.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int x; cin >> x;
            prob[i][j] = 1LL * x * mod_pow(100, MOD - 2) % MOD;
            if (prob[i][j] < 0) prob[i][j] += MOD;
        }
    }

    if (N == 1) {
        cout << prob[0][0] << '\n';
        return 0;
    }

    half = N / 2;
    vi tmp;
    build_first(1, 0, tmp);

    for (int i = 0; i < (1 << 20); ++i) dp1[i] %= MOD;

    for (int b = 0; b < 20; ++b) {
        for (int s = 0; s < (1 << 20); ++s) {
            if (s >> b & 1) {
                dp1[s] = (dp1[s] + dp1[s ^ (1 << b)]) % MOD;
            }
        }
    }

    i64 total = dp1[(1 << 20) - 1];

    tmp.clear();
    build_second(1, half, tmp);

    for (int i = 0; i < (1 << 20); ++i) dp2[i] %= MOD;

    fill(rev1, rev1 + (1 << 20), -1);
    int idx1 = 0;
    for (int s = 0; s < (1 << N); ++s) {
        if (__builtin_popcount(s) != half) continue;
        rev1[s] = idx1++;
    }

    fill(rev2, rev2 + (1 << 20), -1);
    idx1 = 0;
    int corr[25] = {};
    for (int s = 0; s < (1 << N); ++s) {
        if (__builtin_popcount(s) != N - half) continue;
        corr[idx1] = rev1[(1 << N) - 1 - s];
        rev2[s] = idx1++;
    }

    i64 answer = 0;
    for (int s = 0; s < (1 << idx1); ++s) {
        i64 val = dp2[s];
        int mask = 0;
        for (int b = 0; b < idx1; ++b) {
            if (s >> b & 1) continue;
            mask |= 1 << corr[b];
        }
        i64 diff = (total - dp1[mask] + MOD) % MOD;
        answer = (answer + val * diff) % MOD;
    }

    cout << answer << '\n';
    return 0;
}
